#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "kg·m/s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::KilogramMeterPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kg·m/s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::KilogramMeterPerSecond))
    );
    assert_eq!("N·s".parse::<ImpulseUnit>(), Ok(ImpulseUnit::NewtonSecond));
    assert_eq!(
        format!("2.5 {}", "N·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::NewtonSecond))
    );
    assert_eq!(
        "nN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::NanonewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "nN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::NanonewtonSecond))
    );
    assert_eq!(
        "µN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::MicronewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "µN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::MicronewtonSecond))
    );
    assert_eq!(
        "mN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::MillinewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "mN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::MillinewtonSecond))
    );
    assert_eq!(
        "cN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::CentinewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "cN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::CentinewtonSecond))
    );
    assert_eq!(
        "dN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::DecinewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "dN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::DecinewtonSecond))
    );
    assert_eq!(
        "daN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::DecanewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "daN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::DecanewtonSecond))
    );
    assert_eq!(
        "kN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::KilonewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "kN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::KilonewtonSecond))
    );
    assert_eq!(
        "MN·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::MeganewtonSecond)
    );
    assert_eq!(
        format!("2.5 {}", "MN·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::MeganewtonSecond))
    );
    assert_eq!(
        "lb·ft/s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::PoundFootPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lb·ft/s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::PoundFootPerSecond))
    );
    assert_eq!(
        "lbf·s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::PoundForceSecond)
    );
    assert_eq!(
        format!("2.5 {}", "lbf·s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::PoundForceSecond))
    );
    assert_eq!(
        "slug·ft/s".parse::<ImpulseUnit>(),
        Ok(ImpulseUnit::SlugFootPerSecond)
    );
    assert_eq!(
        format!("2.5 {}", "slug·ft/s").parse::<Impulse>(),
        Ok(Impulse::new(2.5, ImpulseUnit::SlugFootPerSecond))
    );
    assert_eq!(
        "1 not-a-unit".parse::<Impulse>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = Impulse::from_base(6.0);
    let b = Impulse::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = Impulse::<i64>::from_base(7);
    let b = Impulse::<i64>::from_base(2);
    assert_eq!(a + b, Impulse::from_base(9));
    assert_eq!(a % b, Impulse::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!([a, b].iter().sum::<Impulse<i64>>(), Impulse::from_base(9));
}
